/**
 * Black-box tests for the Marketplace taxonomy in js/data-item-categories.js
 * (generated by scripts/gen-item-categories.cjs from items.xml).
 *
 * items.xml spells the SAME in-game bucket several ways — legacy keys that were
 * never cleaned up as content shipped. Copied through verbatim, each spelling
 * became its own entry in the Category ▸ Subcategory pickers, so filtering to a
 * bucket silently hid part of it:
 *
 *   • the Smuggler / Brecilien / Avalonian capes sat under a whole separate
 *     "Capes" category (shopcategory="capes", shopsubcategory1=
 *     "accessoires_capes_*") instead of Accessories ▸ Cape — picking "Cape"
 *     showed 71 of the 86 capes this app knows (reported bug);
 *   • every Crystal League weapon and all eight Shapeshifter staves sat under a
 *     "Weapons" category instead of Melee / Magic / Ranged;
 *   • the Crystal off-hands used "booktype" / "shieldtype" / "torchtype";
 *   • "potions" vs "potion", "raremounts" vs "rare_mount", and the Crystal
 *     artifacts under "weapons" / "offhands" rather than *_artefact.
 *
 * These assert the folded taxonomy, plus the structural invariants that keep a
 * future items.xml refresh from re-introducing the split.
 *
 * Run: node tests/item-categories-taxonomy.test.cjs
 */

const assert = require("assert");
const {
  MARKET_CATEGORY_TREE,
  MARKET_CATEGORY_BY_BASE,
  getMarketCategory,
} = require("../js/data-item-categories.js");

let passed = 0;
let failed = 0;
function test(name, fn) {
  try {
    fn();
    passed++;
    console.log(`  PASS: ${name}`);
  } catch (e) {
    failed++;
    console.log(`  FAIL: ${name} — ${e.message}`);
  }
}

const packed = (id) => {
  const hit = getMarketCategory(id);
  return hit ? `${hit.category}|${hit.subcategory}` : null;
};

const catKeys = MARKET_CATEGORY_TREE.map((c) => c.key);
const subKeysOf = (catKey) => {
  const c = MARKET_CATEGORY_TREE.find((x) => x.key === catKey);
  return c ? c.subs.map((s) => s.key) : [];
};

console.log("Marketplace Taxonomy Tests\n");

// ── capes: one bucket, not three ────────────────────────────────────────────

test('no separate "capes" top-level category', () => {
  assert.ok(!catKeys.includes("capes"), "tree still lists a Capes category");
});

[
  "T4_CAPEITEM_SMUGGLER",
  "T8_CAPEITEM_SMUGGLER",
  "T4_CAPEITEM_FW_BRECILIEN",
  "T8_CAPEITEM_FW_BRECILIEN",
  "T4_CAPEITEM_AVALON",
  "T8_CAPEITEM_AVALON",
  "T8_CAPEITEM_AVALON@4",
  "T4_CAPE", // the plain city cape, which was always right
  "T8_CAPEITEM_UNDEAD",
  "T8_CAPEITEM_FW_MARTLOCK",
].forEach((id) => {
  test(`${id} is Accessories ▸ Cape`, () => {
    assert.strictEqual(packed(id), "accessories|cape");
  });
});

test("every CAPEITEM base id in the map lands in one bucket", () => {
  const buckets = new Set();
  Object.keys(MARKET_CATEGORY_BY_BASE)
    .filter((base) => /^CAPE(ITEM)?(_|$)/.test(base) && !base.endsWith("_BP"))
    .forEach((base) => buckets.add(MARKET_CATEGORY_BY_BASE[base]));
  assert.deepStrictEqual([...buckets], ["accessories|cape"]);
});

test('"Cape" is not also a subcategory of Armor', () => {
  assert.ok(!subKeysOf("armor").includes("cape"));
});

// ── Crystal League weapons + Shapeshifter staves ────────────────────────────

test('no separate "weapons" top-level category', () => {
  assert.ok(!catKeys.includes("weapons"), "tree still lists a Weapons category");
});

[
  ["T8_2H_SHAPESHIFTER_AVALON", "magic|shapeshifterstaff"],
  ["T8_2H_SHAPESHIFTER_HELL", "magic|shapeshifterstaff"],
  ["T8_2H_ARCANESTAFF_CRYSTAL", "magic|arcanestaff"],
  ["T8_2H_FROSTSTAFF_CRYSTAL", "magic|froststaff"],
  ["T8_2H_HOLYSTAFF_CRYSTAL", "magic|holystaff"],
  ["T8_MAIN_CURSEDSTAFF_CRYSTAL", "magic|cursestaff"],
  ["T8_MAIN_FIRESTAFF_CRYSTAL", "magic|firestaff"],
  ["T8_MAIN_NATURESTAFF_CRYSTAL", "magic|naturestaff"],
  ["T8_2H_BOW_CRYSTAL", "ranged|bow"],
  ["T8_2H_DUALCROSSBOW_CRYSTAL", "ranged|crossbow"],
  ["T8_2H_HAMMER_CRYSTAL", "melee|hammer"],
  ["T8_2H_KNUCKLES_CRYSTAL", "melee|knuckles"],
  ["T8_2H_SCYTHE_CRYSTAL", "melee|axe"],
  ["T8_2H_GLAIVE_CRYSTAL", "melee|spear"],
  ["T8_2H_DAGGERPAIR_CRYSTAL", "melee|dagger"],
  ["T8_2H_DOUBLEBLADEDSTAFF_CRYSTAL", "melee|quarterstaff"],
  ["T8_MAIN_MACE_CRYSTAL", "melee|mace"],
  ["T8_MAIN_SWORD_CRYSTAL", "melee|sword"],
].forEach(([id, expected]) => {
  test(`${id} is ${expected}`, () => {
    assert.strictEqual(packed(id), expected);
  });
});

test("the Crystal weapon sits with the ordinary weapons of its line", () => {
  // The whole point of the fold: picking "Magic ▸ Arcane Staff" must return the
  // Crystal staff alongside the Elder's/Witchwork ones.
  assert.strictEqual(packed("T8_2H_ARCANESTAFF_CRYSTAL"), packed("T8_2H_ARCANESTAFF"));
  assert.strictEqual(packed("T8_MAIN_SWORD_CRYSTAL"), packed("T8_MAIN_SWORD"));
});

// ── off-hand + potion + mount duplicate spellings ───────────────────────────

test("off-hand has no *type duplicate subcategories", () => {
  const subs = subKeysOf("offhand");
  ["booktype", "shieldtype", "torchtype"].forEach((k) =>
    assert.ok(!subs.includes(k), `offhand still lists ${k}`),
  );
});

[
  ["T8_OFF_TOME_CRYSTAL", "offhand|book"],
  ["T8_OFF_SHIELD_CRYSTAL", "offhand|shield"],
  ["T8_OFF_TORCH_CRYSTAL", "offhand|torch"],
].forEach(([id, expected]) => {
  test(`${id} is ${expected}`, () => {
    assert.strictEqual(packed(id), expected);
  });
});

test('consumables has no "potions" duplicate of "potion"', () => {
  assert.ok(!subKeysOf("consumables").includes("potions"));
});

[
  "T4_POTION_HEAL",
  "T4_POTION_ACID",
  "T4_POTION_BERSERK",
  "T5_POTION_MOB_RESET",
].forEach((id) => {
  test(`${id} is Consumables ▸ Potion`, () => {
    assert.strictEqual(packed(id), "consumables|potion");
  });
});

test('mounts has no "raremounts" duplicate of "rare_mount"', () => {
  assert.ok(!subKeysOf("mounts").includes("raremounts"));
});

test("T8_MOUNT_OWL_FW_BRECILIEN is Mounts ▸ Rare Mount", () => {
  assert.strictEqual(packed("T8_MOUNT_OWL_FW_BRECILIEN"), "mounts|rare_mount");
});

// ── Crystal artifacts follow their weapon line ──────────────────────────────

test("artifacts have no generic weapons/offhands subcategories", () => {
  const subs = subKeysOf("artefacts");
  ["weapons", "offhands"].forEach((k) =>
    assert.ok(!subs.includes(k), `artefacts still lists ${k}`),
  );
});

[
  ["T8_ARTEFACT_2H_BOW_CRYSTAL", "artefacts|ranged_artefact"],
  ["T8_ARTEFACT_2H_ARCANESTAFF_CRYSTAL", "artefacts|magic_artefact"],
  ["T8_ARTEFACT_2H_HAMMER_CRYSTAL", "artefacts|melee_artefact"],
  ["T8_ARTEFACT_OFF_SHIELD_CRYSTAL", "artefacts|offhand_artefact"],
  ["T8_ARTEFACT_OFF_TOME_CRYSTAL", "artefacts|offhand_artefact"],
].forEach(([id, expected]) => {
  test(`${id} is ${expected}`, () => {
    assert.strictEqual(packed(id), expected);
  });
});

// ── structural invariants ───────────────────────────────────────────────────

test("every packed value in the map exists in the tree", () => {
  const known = new Set();
  MARKET_CATEGORY_TREE.forEach((c) => {
    known.add(c.key);
    c.subs.forEach((s) => known.add(`${c.key}|${s.key}`));
  });
  const orphans = [...new Set(Object.values(MARKET_CATEGORY_BY_BASE))].filter(
    (v) => !known.has(v),
  );
  assert.deepStrictEqual(orphans, []);
});

test("every subcategory in the tree is carried by at least one item", () => {
  const used = new Set(Object.values(MARKET_CATEGORY_BY_BASE));
  const empty = [];
  MARKET_CATEGORY_TREE.forEach((c) => {
    c.subs.forEach((s) => {
      if (!used.has(`${c.key}|${s.key}`)) empty.push(`${c.key}|${s.key}`);
    });
  });
  assert.deepStrictEqual(empty, []);
});

test("no category key is also spelled as one of its own aliases", () => {
  // "offhands"/"offhand" and "farmables"/"farming" were the original pair; the
  // fold must leave exactly one spelling of each in the tree.
  ["offhands", "farmables", "capes", "weapons"].forEach((alias) =>
    assert.ok(!catKeys.includes(alias), `${alias} survived as a category`),
  );
});

test("no label is a raw run-together key", () => {
  const ugly = [];
  MARKET_CATEGORY_TREE.forEach((c) => {
    c.subs.forEach((s) => {
      if (/accessoires/i.test(s.label) || /accessoires/i.test(s.key)) {
        ugly.push(`${c.key}|${s.key}`);
      }
    });
  });
  assert.deepStrictEqual(ugly, []);
});

test("a journal's _EMPTY/_FULL market suffix keeps its category", () => {
  // items.xml carries the carried journal alone (`T2_JOURNAL_WOOD`); the two
  // ids that actually trade are `_EMPTY` and `_FULL`, and without the strip
  // every journal row answered no category pick at all.
  assert.strictEqual(packed("T8_JOURNAL_HIDE_FULL"), "products|journal");
  assert.strictEqual(packed("T2_JOURNAL_WOOD_EMPTY"), "products|journal");
  assert.strictEqual(packed("T8_JOURNAL_TROPHY_FISHING_FULL"), "products|journal");
  assert.strictEqual(packed("T4_JOURNAL_MERCENARY_EMPTY"), packed("T4_JOURNAL_MERCENARY"));
});

test("crests are Artifacts ▸ Capes, not Accessories ▸ Cape", () => {
  // The crest is the cape's blueprint and sells in its own market bucket.
  assert.strictEqual(packed("T4_CAPEITEM_UNDEAD_BP"), "artefacts|capes");
  assert.strictEqual(packed("T8_CAPEITEM_FW_CAERLEON_BP"), "artefacts|capes");
});

test("a tier prefix, _LEVELn and @n never change an item's category", () => {
  assert.strictEqual(packed("T4_CAPEITEM_AVALON"), packed("T8_CAPEITEM_AVALON@3"));
  assert.strictEqual(packed("T4_PLANKS"), packed("T8_PLANKS_LEVEL3@3"));
});

// ── resources: raw and refined are two categories ───────────────────────────

[
  ["T4_ORE", "resources|ore"],
  ["T4_ORE_LEVEL1@1", "resources|ore"],
  ["T5_HIDE", "resources|hide"],
  ["T6_FIBER", "resources|fiber"],
  ["T7_WOOD", "resources|wood"],
  ["T8_ROCK", "resources|rock"],
  ["T4_METALBAR", "refinedresources|metalbar"],
  ["T4_METALBAR_LEVEL2@2", "refinedresources|metalbar"],
  ["T5_LEATHER", "refinedresources|leather"],
  ["T6_CLOTH", "refinedresources|cloth"],
  ["T7_PLANKS", "refinedresources|planks"],
  ["T8_STONEBLOCK", "refinedresources|stoneblock"],
].forEach(([id, want]) => {
  test(`${id} is ${want}`, () => {
    assert.strictEqual(packed(id), want);
  });
});

test("resources subs are exactly the five raw kinds", () => {
  assert.deepStrictEqual(subKeysOf("resources").slice().sort(), ["fiber", "hide", "ore", "rock", "wood"]);
});

test("refinedresources has its label and the five refined subs", () => {
  const c = MARKET_CATEGORY_TREE.find((x) => x.key === "refinedresources");
  assert.ok(c, "refinedresources missing from tree");
  assert.strictEqual(c.label, "Refined Resources");
  assert.deepStrictEqual(subKeysOf("refinedresources").slice().sort(), ["cloth", "leather", "metalbar", "planks", "stoneblock"]);
});

test("refinedresources sits right after resources", () => {
  assert.strictEqual(catKeys.indexOf("refinedresources"), catKeys.indexOf("resources") + 1);
});

test("a city heart is still cityresources", () => {
  const c = MARKET_CATEGORY_TREE.find((x) => x.key === "cityresources");
  assert.ok(c && c.subs.some((s) => s.key === "beastheart"));
  assert.ok(!subKeysOf("refinedresources").includes("beastheart"));
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed === 0 ? 0 : 1);
